CREATE TYPE "DrawingTakeoffStatus" AS ENUM ('REVIEW_REQUIRED', 'CONFIRMED', 'CONVERTED', 'CANCELLED');
CREATE TYPE "TakeoffQuantityProvenance" AS ENUM ('DRAWING_COUNTED', 'DRAWING_MEASURED', 'CALCULATED', 'USER_PROVIDED', 'AI_INTERPRETED', 'CATALOG_MAPPED', 'NEEDS_CONFIRMATION');
CREATE TABLE "DrawingTakeoffSession" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "createdByUserId" TEXT NOT NULL, "sourceFileName" TEXT NOT NULL, "sourceMimeType" TEXT NOT NULL, "sourceSizeBytes" INTEGER NOT NULL, "sourceSha256" TEXT NOT NULL, "userIntent" TEXT NOT NULL, "discipline" TEXT NOT NULL DEFAULT 'CCTV_LOW_VOLTAGE', "status" "DrawingTakeoffStatus" NOT NULL DEFAULT 'REVIEW_REQUIRED', "confirmedAt" TIMESTAMP(3), "convertedAt" TIMESTAMP(3), "quotationId" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DrawingTakeoffSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DrawingTakeoffLine" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "position" INTEGER NOT NULL, "itemName" TEXT NOT NULL, "description" TEXT, "quantity" DECIMAL(18,3), "unitName" TEXT, "provenance" "TakeoffQuantityProvenance" NOT NULL, "evidence" TEXT, "confidence" DECIMAL(5,4), "isConfirmed" BOOLEAN NOT NULL DEFAULT false, "confirmedById" TEXT, "confirmedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DrawingTakeoffLine_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DrawingTakeoffSession_companyId_sourceSha256_userIntent_key" ON "DrawingTakeoffSession"("companyId", "sourceSha256", "userIntent");
CREATE INDEX "DrawingTakeoffSession_companyId_status_createdAt_idx" ON "DrawingTakeoffSession"("companyId", "status", "createdAt");
CREATE INDEX "DrawingTakeoffSession_companyId_quotationId_idx" ON "DrawingTakeoffSession"("companyId", "quotationId");
CREATE UNIQUE INDEX "DrawingTakeoffLine_sessionId_position_key" ON "DrawingTakeoffLine"("sessionId", "position");
CREATE INDEX "DrawingTakeoffLine_sessionId_isConfirmed_idx" ON "DrawingTakeoffLine"("sessionId", "isConfirmed");
ALTER TABLE "DrawingTakeoffSession" ADD CONSTRAINT "DrawingTakeoffSession_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DrawingTakeoffLine" ADD CONSTRAINT "DrawingTakeoffLine_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DrawingTakeoffSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
